package com.cardcombat;import java.util.*;import org.bukkit.*;import org.bukkit.entity.Player;
public final class MatchmakingManager{private final CardCombatPlugin p;private final LinkedList<UUID>q=new LinkedList<UUID>();public MatchmakingManager(CardCombatPlugin p){this.p=p;}public synchronized void join(Player x){if(!p.isBattleMode(x)){x.sendMessage(ChatColor.RED+"Enter BattleCards mode first.");return;}if(p.challenges().isInMatch(x.getUniqueId()))return;if(q.contains(x.getUniqueId())){x.sendMessage(ChatColor.YELLOW+"You are already queued.");return;}q.add(x.getUniqueId());x.sendMessage(ChatColor.GREEN+"Joined official matchmaking. Position: "+q.size());pair();}public synchronized void leave(Player x){q.remove(x.getUniqueId());x.sendMessage(ChatColor.YELLOW+"Left matchmaking.");}public synchronized void remove(UUID u){q.remove(u);}public synchronized int position(UUID u){return q.indexOf(u)<0?0:q.indexOf(u)+1;}private void pair(){while(q.size()>=2){UUID a=q.removeFirst(),b=q.removeFirst();Player pa=Bukkit.getPlayer(a),pb=Bukkit.getPlayer(b);if(pa!=null&&pb!=null)p.challenges().startOfficial(pa,pb);}}public synchronized void shutdown(){q.clear();}}
